return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'SION UNAC - Inscripcion recibida: ' + item.json.program,
    name: item.json.name || 'Aspirante',
    program: item.json.program,
    schedule: item.json.schedule,
    inscriptionId: item.json.inscriptionId,
    status: item.json.status,
    body: 'Hola ' + (item.json.name || 'Aspirante') + ', recibimos tu inscripcion al programa ' + item.json.program + ' (jornada ' + item.json.schedule + '). Estado: ' + item.json.status + '.',
    sentAt: new Date().toISOString()
  }
}));
